// Finanz_Web_NavBar: zentrale Navigationsleiste fuer alle Web-Seiten dieses Systems
// (Human-in-the-Loop Phase 3, HUMAN_IN_THE_LOOP_ARCHITECTURE.md Abschnitt 2.1).
// Analog dem bewaehrten ALLRIS_Web_NavBar-Muster: {currentPage} rein, {navHtml} raus.
// Aufrufer MUSS diesen Sub-Workflow PARALLEL zum eigenen Trigger aufrufen (nicht inline in
// einer POST-Verarbeitungskette), sonst wird $json ueberschrieben und Formulardaten gehen
// verloren - siehe Architekturdokument.

const currentPage = $json.currentPage || '';

// Neue Human-in-the-Loop-Seiten zuerst (nach den Nutzer-Entscheidungen organisiert, nicht nach
// Workflow-Nummern), bestehende Seiten danach.
const PAGES = [
  ['heute', 'Heute'],
  ['heute-handeln', 'Handeln'],
  ['trade-review', 'Positionen'],
  ['news-pruefen', 'News'],
  ['lernen-feedback', 'Feedback'],
  ['regeln', 'Regeln'],
  ['simulation-uebersicht', 'Simulationen'],
  ['aktien-status', 'System'],
];

const MEHR_PAGES = [
  ['aktien-watchlist', 'Watchlist'],
  ['rss-quellen', 'RSS-Quellen'],
  ['lernvorschlaege', 'Lernvorschlaege'],
  ['historische-marktdaten', 'Marktdaten-Import'],
  ['historische-nachrichten', 'Nachrichten-Import'],
  ['historische-news-lernkandidaten', 'News-Lernkandidaten'],
  ['historische-news-ausschluesse', 'Ausschlussregeln'],
  ['historische-simulation', 'Simulationslaeufe'],
    ['simulation-vergleich', 'Sim-Vergleich'],
];

function link(path, label, active) {
  const style = active
    ? 'color:#fff;text-decoration:none;font-weight:600;border-bottom:2px solid #5b8def;padding-bottom:2px;'
    : 'color:#8ab4f8;text-decoration:none;';
  return `<a href="/webhook/${path}" style="${style}">${label}</a>`;
}

const mainLinks = PAGES.map(([path, label]) => link(path, label, path === currentPage)).join('');
const mehrLinks = MEHR_PAGES.map(([path, label]) => link(path, label, path === currentPage)).join('');

const navHtml =
  '<div style="background:#232323;border:1px solid #444;border-radius:6px;padding:8px 14px;margin-bottom:12px;display:flex;flex-wrap:wrap;gap:4px 16px;font-size:14px;">' +
  mainLinks +
  '</div>' +
  '<details style="margin-bottom:20px;">' +
  '<summary style="cursor:pointer;color:#9aa0a6;font-size:12px;padding:2px 0;">Weitere Seiten</summary>' +
  '<div style="background:#1a1c20;border:1px solid #333;border-radius:6px;padding:8px 14px;margin-top:6px;display:flex;flex-wrap:wrap;gap:4px 16px;font-size:12px;">' +
  mehrLinks +
  '</div>' +
  '</details>';

return [{ json: { navHtml } }];
